   351  /**
   352   * xmlParserInputGrow:
   353   * @in:  an XML parser input
   354   * @len:  an indicative size for the lookahead
   355   *
   356   * DEPRECATED: Don't use.
   357   *
   358   * This function increase the input for the parser. It tries to
   359   * preserve pointers to the input buffer, and keep already read data
   360   *
   361   * Returns the amount of char read, or -1 in case of error, 0 indicate the
   362   * end of this entity
   363   */
   364  int
   365  xmlParserInputGrow(xmlParserInputPtr in, int len) {
   366      int ret;
   367      size_t indx;
   368
   369      if ((in == NULL) || (len < 0)) return(-1);
   370  #ifdef DEBUG_INPUT
   371      xmlGenericError(xmlGenericErrorContext, "Grow\n");
   372  #endif
   373      if (in->buf == NULL) return(-1);
   374      if (in->base == NULL) return(-1);
   375      if (in->cur == NULL) return(-1);
   376      if (in->buf->buffer == NULL) return(-1);
   377
   378      /* Don't grow memory buffers. */
   379      if ((in->buf->encoder == NULL) && (in->buf->readcallback == NULL))
   380          return(0);
   381
   382      CHECK_BUFFER(in);
   383
   384      indx = in->cur - in->base;
   385      if (xmlBufUse(in->buf->buffer) > (unsigned int) indx + INPUT_CHUNK) {
   386
   387          CHECK_BUFFER(in);
   388
   389          return(0);
   390      }
